import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { NavbarComponent } from '../shared/navbar.component';
import { DonationModalComponent } from '../shared/donation-modal.component';

interface Campaign {
  id: number;
  title: string;
  description: string;
  image: string;
  progress: number;
  target: number;
  category: string;
  status: 'active' | 'completed' | 'paused';
}

interface Association {
  id: number;
  name: string;
  logo?: string;
  cover: string;
  tagline: string;
  description: string;
  fullDescription: string;
  verified: boolean;
  email: string;
  location: string;
  foundedYear: number;
  stats: {
    totalDonations: number;
    campaignCount: number;
    peopleHelped: number;
    donorsCount: number;
  };
  campaigns: Campaign[];
  transparency: {
    operatingCosts: number;
    directAid: number;
    programsEducation: number;
    adminOverhead: number;
  };
}

@Component({
  selector: 'app-association-detail',
  standalone: true,
  imports: [CommonModule, NavbarComponent, DonationModalComponent],
  templateUrl: './association-detail.component.html',
  styleUrl: './association-detail.component.css'
})
export class AssociationDetailComponent implements OnInit {

  association: Association = {
    id: 1,
    name: 'Solidarité Plus',
    cover: '/assets/images/placeholders/association-cover-placeholder.svg',
    tagline: 'Ensemble, construisons une communauté plus solidaire',
    description: 'Association d\'aide alimentaire et sociale depuis 15 ans',
    fullDescription: `Solidarité Plus est une association reconnue et vérifiée qui œuvre depuis 15 ans 
pour l'aide alimentaire et le soutien social des familles en difficulté.

Notre mission est de :
• Fournir une aide alimentaire d'urgence aux familles en situation de précarité
• Organiser des actions d'aide éducative et de sensibilisation
• Créer des liens communautaires solides basés sur l'entraide
• Transparence totale dans l'utilisation des fonds collectés

Nos domaines d'action :
- Distributions alimentaires régulières
- Programmes de sensibilisation nutritionnelle
- Accompagnement social des familles
- Événements communautaires d'entraide

Nous croyons fermement que chacun mérite l'accès à l'alimentation de qualité et au soutien social.`,
    verified: true,
    email: 'contact@solidariteplus.org',
    location: 'Tunis, Tunisie',
    foundedYear: 2011,
    stats: {
      totalDonations: 450000,
      campaignCount: 28,
      peopleHelped: 12500,
      donorsCount: 3200
    },
    campaigns: [
      {
        id: 1,
        title: 'Aide alimentaire d\'urgence - 50 familles',
        description: 'Distribution de paniers alimentaires aux familles en détresse',
        image: '/assets/images/placeholders/request-placeholder.svg',
        progress: 1850,
        target: 3000,
        category: 'Alimentation',
        status: 'active'
      },
      {
        id: 2,
        title: 'Soutien hivernal pour sans-abri',
        description: 'Aide hivernale : vêtements, couvertures, repas chauds',
        image: '/assets/images/placeholders/request-placeholder.svg',
        progress: 2400,
        target: 4000,
        category: 'Urgence',
        status: 'active'
      },
      {
        id: 3,
        title: 'Repas scolaires pour enfants défavorisés',
        description: 'Programme de nutrition pour enfants scolarisés en situation de précarité',
        image: '/assets/images/placeholders/request-placeholder.svg',
        progress: 3100,
        target: 5000,
        category: 'Éducation',
        status: 'active'
      },
      {
        id: 4,
        title: 'Campagne de sensibilisation nutritionnelle',
        description: 'Ateliers et formations sur l\'alimentation saine',
        image: '/assets/images/placeholders/request-placeholder.svg',
        progress: 1200,
        target: 2000,
        category: 'Formation',
        status: 'active'
      }
    ],
    transparency: {
      operatingCosts: 85000,
      directAid: 280000,
      programsEducation: 65000,
      adminOverhead: 20000
    }
  };

  yearsActive: number = 0;
  sidebarSticky = false;
  isDonationModalOpen = false;

  constructor(private router: Router) {}

  ngOnInit() {
    this.yearsActive = new Date().getFullYear() - this.association.foundedYear;
    window.addEventListener('scroll', this.handleScroll.bind(this));
  }

  handleScroll() {
    this.sidebarSticky = window.scrollY > 300;
  }

  getProgressPercent(progress: number, target: number): number {
    return (progress / target) * 100;
  }

  viewCampaigns() {
    const element = document.querySelector('.campaigns-section') as HTMLElement;
    const offsetTop = element?.offsetTop || 0;
    window.scrollTo({ top: offsetTop, behavior: 'smooth' });
  }

  supportAssociation() {
    this.isDonationModalOpen = true;
  }

  onDonationClosed() {
    this.isDonationModalOpen = false;
  }

  onDonationCompleted(donation: any) {
    console.log('Donation completed:', donation);
    // Mettre à jour les stats de l'association
    this.association.stats.totalDonations += donation.amount;
    this.association.stats.donorsCount += 1;
  }

  shareCampaign() {
    if (navigator.share) {
      navigator.share({
        title: this.association.name,
        text: this.association.tagline,
        url: window.location.href
      });
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Lien copié dans le presse-papiers');
    }
  }

  getLogoInitial(): string {
    return this.association.name.charAt(0);
  }

  getCampaignStatusClass(status: string): string {
    return `status-${status}`;
  }

  getCampaignStatusLabel(status: string): string {
    switch (status) {
      case 'active':
        return 'Actif';
      case 'completed':
        return 'Complété';
      case 'paused':
        return 'Pausé';
      default:
        return 'Actif';
    }
  }
}
