import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { Router } from '@angular/router';

import { NavbarComponent } from '../shared/navbar.component';
import { LoggedInNavbarComponent } from '../shared/logged-in-navbar.component';
import { AssociationNavbarComponent } from '../shared/association-navbar.component';
import { DonationModalComponent } from '../shared/donation-modal.component';
import { AuthService } from '../auth/auth.service';
import { UserDataService } from '../user/user-data.service';
import { UserRole } from '../auth/auth.models';

interface Request {
  id: number;
  title: string;
  category: string;
  urgency: 'low' | 'medium' | 'high';
  image: string;
  description: string;
  detailedDescription: string;
  location: string;
  publishedDate: string;
  progress: number;
  target: number;
  contributors: number;
  daysRemaining: number;
  organization: {
    name: string;
    logo?: string;
    verified: boolean;
    description: string;
  };
}

interface RelatedRequest {
  id: number;
  title: string;
  category: string;
  image: string;
  progress: number;
  target: number;
  urgency: 'low' | 'medium' | 'high';
}

@Component({
  selector: 'app-request-detail',
  standalone: true,
  imports: [
    CommonModule,
    NavbarComponent,
    LoggedInNavbarComponent,
    AssociationNavbarComponent,
    DonationModalComponent
  ],
  templateUrl: './request-detail.component.html',
  styleUrl: './request-detail.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class RequestDetailComponent {
  private readonly router = inject(Router);
  private readonly userData = inject(UserDataService);
  private readonly auth = inject(AuthService);

  readonly role = signal<UserRole | null>(null);
  readonly isLoggedIn = signal(false);
  readonly isAssociation = computed(() => this.role() === 'association');

  readonly isFavorite = signal(false);
  readonly sidebarSticky = signal(false);
  readonly isDonationModalOpen = signal(false);

  readonly request = signal<Request>({
    id: 1,
    title: 'Aide alimentaire pour 50 familles en détresse',
    category: 'Alimentation',
    urgency: 'high',
    image: '/assets/images/placeholders/request-placeholder.svg',
    description: "Un projet d'aide alimentaire urgente pour 50 familles en situation de vulnérabilité",
    detailedDescription: `Notre association s'engage à fournir une aide alimentaire d'urgence à 50 familles 
 en situation de grande vulnérabilité. Beaucoup de ces familles n'ont pas accès à des repas réguliers 
 et leurs enfants souffrent de malnutrition.

 Avec votre aide, nous pourrons distribuer des paniers alimentaires contenant :
 • Produits de base (riz, pâtes, huile)
 • Fruits et légumes frais
 • Protéines (œufs, conserves)
 • Produits laitiers
 • Articles d'hygiène essentiels

 Chaque panier est conçu pour nourrir une famille pendant deux semaines.

 Les fonds collectés seront utilisés de manière transparente et sécurisée. 
 Un rapport détaillé sera fourni à tous les donateurs.`,
    location: 'Tunis, Ben Arous',
    publishedDate: '2026-04-15',
    progress: 1850,
    target: 3000,
    contributors: 45,
    daysRemaining: 12,
    organization: {
      name: 'Solidarité Plus',
      verified: true,
      description: "Association d'aide alimentaire depuis 15 ans"
    }
  });

  readonly relatedRequests = signal<RelatedRequest[]>([
    {
      id: 2,
      title: 'Scolarité pour enfants défavorisés',
      category: 'Éducation',
      image: '/assets/images/placeholders/request-placeholder.svg',
      progress: 2400,
      target: 4000,
      urgency: 'medium'
    },
    {
      id: 3,
      title: "Couverture médicale d'urgence",
      category: 'Santé',
      image: '/assets/images/placeholders/request-placeholder.svg',
      progress: 1200,
      target: 2500,
      urgency: 'high'
    },
    {
      id: 4,
      title: 'Rénovation refuge hivernal',
      category: 'Logement',
      image: '/assets/images/placeholders/request-placeholder.svg',
      progress: 3100,
      target: 5000,
      urgency: 'low'
    }
  ]);

  constructor() {
    this.isLoggedIn.set(Boolean(this.auth.getToken()));
    this.role.set(this.auth.getRole() as UserRole | null);

    window.addEventListener('scroll', this.handleScroll.bind(this));
    this.loadFavorite();
  }

  loadFavorite() {
    if (!this.auth.getToken() || this.isAssociation()) {
      return;
    }

    this.userData.getFavorites().subscribe({
      next: (response) => {
        if (response.success) {
          this.isFavorite.set(
            response.data.some((item) => item.request_id === this.request().id)
          );
        }
      }
    });
  }

  toggleFavorite() {
    if (!this.auth.getToken()) {
      return;
    }

    if (this.isFavorite()) {
      this.userData.removeFavorite(this.request().id).subscribe({
        next: (response) => {
          if (response.success) {
            this.isFavorite.set(false);
          }
        }
      });
      return;
    }

    this.userData.addFavorite(this.request().id).subscribe({
      next: (response) => {
        if (response.success) {
          this.isFavorite.set(true);
        }
      }
    });
  }

  handleScroll() {
    this.sidebarSticky.set(window.scrollY > 300);
  }

  getProgressPercent(progress: number, target: number): number {
    return (progress / target) * 100;
  }

  getUrgencyLabel(urgency: string): string {
    switch (urgency) {
      case 'high':
        return 'Urgent';
      case 'medium':
        return 'Important';
      case 'low':
        return 'Standard';
      default:
        return 'Standard';
    }
  }

  helpNow() {
    this.isDonationModalOpen.set(true);
  }

  onDonationClosed() {
    this.isDonationModalOpen.set(false);
  }

  onDonationCompleted(donation: { amount: number }) {
    this.request.update((current) => ({
      ...current,
      progress: current.progress + donation.amount,
      contributors: current.contributors + 1
    }));
  }

  shareRequest() {
    if (navigator.share) {
      navigator.share({
        title: this.request().title,
        text: this.request().description,
        url: window.location.href
      });
    } else {
      alert('Lien copié dans le presse-papiers');
      navigator.clipboard.writeText(window.location.href);
    }
  }

  getLogoInitial(): string {
    return this.request().organization.name.charAt(0);
  }

  collaborate() {
    this.router.navigate(['/association/campaigns']);
  }

  supportRequest() {
    this.router.navigate(['/association/campaigns']);
  }

  takeOwnership() {
    this.router.navigate(['/association/campaigns']);
  }

  createCampaignFromRequest() {
    this.router.navigate(['/association/campaigns/new'], {
      queryParams: { parentRequestId: this.request().id }
    });
  }

  contactRequester() {
    const subject = encodeURIComponent(`Demande ${this.request().title}`);
    window.location.href = `mailto:support@sanad.tn?subject=${subject}`;
  }
}
