import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';

import { NavbarComponent } from '../shared/navbar.component';
import { LoggedInNavbarComponent } from '../shared/logged-in-navbar.component';
import { AssociationNavbarComponent } from '../shared/association-navbar.component';
import { AuthService } from '../auth/auth.service';
import { UserDataService } from '../user/user-data.service';
import { UserRole } from '../auth/auth.models';

interface Request {
  id: number;
  title: string;
  description: string;
  organization: string;
  location: string;
  category: string;
  urgency: 'low' | 'medium' | 'high';
  progress: number;
  target: number;
  image?: string;
}

@Component({
  selector: 'app-explorer',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    RouterLink,
    NavbarComponent,
    LoggedInNavbarComponent,
    AssociationNavbarComponent
  ],
  templateUrl: './explorer.component.html',
  styleUrl: './explorer.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ExplorerComponent {
  private readonly userData = inject(UserDataService);
  private readonly auth = inject(AuthService);
  private readonly router = inject(Router);

  readonly role = signal<UserRole | null>(null);
  readonly isLoggedIn = signal(false);
  readonly isAssociation = computed(() => this.role() === 'association');

  readonly searchQuery = signal('');
  readonly selectedCategory = signal('');
  readonly selectedLocation = signal('');
  readonly selectedUrgency = signal('');
  readonly sortBy = signal<'recent' | 'most-funded' | 'most-urgent'>('recent');

  readonly categories = ['Alimentation', 'Santé', 'Éducation', 'Logement', 'Emploi', 'Bien-être'];
  readonly locations = ['Tunis', 'Sfax', 'Sousse', 'Ariana', 'Ben Arous', 'Manouba'];
  readonly urgencies = ['Basse', 'Moyenne', 'Haute'];

  readonly allRequests = signal<Request[]>([
    {
      id: 1,
      title: 'Aide alimentaire d\'urgence',
      description: 'Soutien pour les familles en situation de crise alimentaire',
      organization: 'Solidarité Plus',
      location: 'Tunis',
      category: 'Alimentation',
      urgency: 'high',
      progress: 850,
      target: 1200,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 2,
      title: 'Scolarité pour enfants',
      description: 'Fournitures scolaires et tutorat pour enfants défavorisés',
      organization: 'Éducation pour Tous',
      location: 'Sfax',
      category: 'Éducation',
      urgency: 'medium',
      progress: 2340,
      target: 3000,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 3,
      title: 'Aide médicale urgente',
      description: 'Couverture de soins pour personnes sans ressources',
      organization: 'Santé Solidaire',
      location: 'Sousse',
      category: 'Santé',
      urgency: 'high',
      progress: 1500,
      target: 2500,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 4,
      title: 'Hébergement d\'urgence',
      description: 'Refuge temporaire et réinsertion pour sans-abri',
      organization: 'Chez Nous',
      location: 'Ariana',
      category: 'Logement',
      urgency: 'high',
      progress: 3200,
      target: 5000,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 5,
      title: 'Formation professionnelle',
      description: 'Cours et certifications pour réinsertion professionnelle',
      organization: 'Avenir Pro',
      location: 'Ben Arous',
      category: 'Emploi',
      urgency: 'medium',
      progress: 1800,
      target: 2400,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 6,
      title: 'Soutien psychosocial',
      description: 'Accompagnement et ressources en santé mentale',
      organization: 'Bien-Être',
      location: 'Manouba',
      category: 'Bien-être',
      urgency: 'low',
      progress: 900,
      target: 1500,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 7,
      title: 'Aide aux personnes âgées',
      description: 'Soins à domicile et assistance quotidienne',
      organization: 'Solidarité Plus',
      location: 'Tunis',
      category: 'Santé',
      urgency: 'medium',
      progress: 600,
      target: 1000,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 8,
      title: 'Kits scolaires d\'urgence',
      description: 'Cahiers, stylos et matériel pour enfants en besoin',
      organization: 'Éducation pour Tous',
      location: 'Sfax',
      category: 'Éducation',
      urgency: 'low',
      progress: 1200,
      target: 1800,
      image: '/assets/images/placeholders/request-placeholder.svg'
    },
    {
      id: 9,
      title: 'Aide alimentaire mensuelle',
      description: 'Panier alimentaire pour familles monoparentales',
      organization: 'Solidarité Plus',
      location: 'Sousse',
      category: 'Alimentation',
      urgency: 'medium',
      progress: 2100,
      target: 3500,
      image: '/assets/images/placeholders/request-placeholder.svg'
    }
  ]);

  readonly favoriteIds = signal(new Set<number>());

  readonly filteredRequests = computed(() => {
    const searchQuery = this.searchQuery().toLowerCase();
    const selectedCategory = this.selectedCategory();
    const selectedLocation = this.selectedLocation();
    const selectedUrgency = this.selectedUrgency();

    const filtered = this.allRequests().filter((request) => {
      const matchesSearch =
        request.title.toLowerCase().includes(searchQuery) ||
        request.organization.toLowerCase().includes(searchQuery);
      const matchesCategory = !selectedCategory || request.category === selectedCategory;
      const matchesLocation = !selectedLocation || request.location === selectedLocation;
      const matchesUrgency =
        !selectedUrgency || this.getUrgencyLabel(request.urgency) === selectedUrgency;

      return matchesSearch && matchesCategory && matchesLocation && matchesUrgency;
    });

    switch (this.sortBy()) {
      case 'most-funded':
        return [...filtered].sort((a, b) => {
          const progressA = (a.progress / a.target) * 100;
          const progressB = (b.progress / b.target) * 100;
          return progressB - progressA;
        });
      case 'most-urgent':
        return [...filtered].sort((a, b) => {
          const urgencyOrder = { high: 0, medium: 1, low: 2 };
          return urgencyOrder[a.urgency] - urgencyOrder[b.urgency];
        });
      default:
        return filtered;
    }
  });

  constructor() {
    this.isLoggedIn.set(Boolean(this.auth.getToken()));
    this.role.set(this.auth.getRole() as UserRole | null);

    if (this.isLoggedIn() && this.isAssociation()) {
      this.router.navigateByUrl('/association/explorer');
      return;
    }

    if (this.isLoggedIn() && !this.isAssociation()) {
      this.loadFavorites();
    }
  }

  loadFavorites() {
    if (!this.auth.getToken()) {
      return;
    }

    this.userData.getFavorites().subscribe({
      next: (response) => {
        if (response.success) {
          this.favoriteIds.set(new Set(response.data.map((item) => item.request_id)));
        }
      }
    });
  }

  toggleFavorite(requestId: number) {
    if (!this.auth.getToken()) {
      return;
    }

    if (this.favoriteIds().has(requestId)) {
      this.userData.removeFavorite(requestId).subscribe({
        next: (response) => {
          if (response.success) {
            const next = new Set(this.favoriteIds());
            next.delete(requestId);
            this.favoriteIds.set(next);
          }
        }
      });
      return;
    }

    this.userData.addFavorite(requestId).subscribe({
      next: (response) => {
        if (response.success) {
          const next = new Set(this.favoriteIds());
          next.add(requestId);
          this.favoriteIds.set(next);
        }
      }
    });
  }

  getProgressPercent(progress: number, target: number): number {
    return Math.round((progress / target) * 100);
  }

  getUrgencyLabel(urgency: 'low' | 'medium' | 'high'): string {
    const labels = { low: 'Basse', medium: 'Moyenne', high: 'Haute' };
    return labels[urgency];
  }

  clearFilters() {
    this.searchQuery.set('');
    this.selectedCategory.set('');
    this.selectedLocation.set('');
    this.selectedUrgency.set('');
    this.sortBy.set('recent');
  }

  openRequest(requestId: number) {
    this.router.navigate(['/request-detail', requestId]);
  }

  collaborate(request: Request) {
    this.router.navigate(['/request-detail', request.id], {
      queryParams: { action: 'collaborer' }
    });
  }

  supportRequest(request: Request) {
    this.router.navigate(['/request-detail', request.id], {
      queryParams: { action: 'soutenir' }
    });
  }

  takeOwnership(request: Request) {
    this.router.navigate(['/request-detail', request.id], {
      queryParams: { action: 'prendre-en-charge' }
    });
  }

  createCampaignFromRequest(request: Request) {
    this.router.navigate(['/association/campaigns/new'], {
      queryParams: { parentRequestId: request.id }
    });
  }

  contactRequester(request: Request) {
    const subject = encodeURIComponent(`Demande ${request.title}`);
    window.location.href = `mailto:support@sanad.tn?subject=${subject}`;
  }
}
