import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { NavbarComponent } from '../shared/navbar.component';

interface Association {
  id: number;
  name: string;
  logo?: string;
  cover?: string;
  location: string;
  category: string;
  description: string;
  verified: boolean;
  campaigns: number;
  totalDonations: number;
}

@Component({
  selector: 'app-associations',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink, NavbarComponent],
  templateUrl: './associations.component.html',
  styleUrl: './associations.component.css'
})
export class AssociationsComponent implements OnInit {
  
  searchQuery = '';
  selectedCategory = '';
  selectedLocation = '';
  sortBy = 'name';

  categories = ['Alimentation', 'Santé', 'Éducation', 'Logement', 'Emploi', 'Bien-être'];
  locations = ['Tunis', 'Sfax', 'Sousse', 'Ariana', 'Ben Arous', 'Manouba'];

  allAssociations: Association[] = [
    {
      id: 1,
      name: 'Solidarité Plus',
      logo: 'S',
      location: 'Tunis',
      category: 'Alimentation',
      description: 'Association d\'aide alimentaire pour les familles en difficulté',
      verified: true,
      campaigns: 12,
      totalDonations: 45000
    },
    {
      id: 2,
      name: 'Éducation pour Tous',
      logo: 'E',
      location: 'Sfax',
      category: 'Éducation',
      description: 'Accès à l\'éducation de qualité pour tous les enfants',
      verified: true,
      campaigns: 15,
      totalDonations: 67500
    },
    {
      id: 3,
      name: 'Santé Solidaire',
      logo: 'S',
      location: 'Sousse',
      category: 'Santé',
      description: 'Couverture médicale pour les personnes sans ressources',
      verified: true,
      campaigns: 8,
      totalDonations: 28000
    },
    {
      id: 4,
      name: 'Chez Nous',
      logo: 'C',
      location: 'Ariana',
      category: 'Logement',
      description: 'Refuge et réinsertion pour les personnes sans-abri',
      verified: true,
      campaigns: 6,
      totalDonations: 35600
    },
    {
      id: 5,
      name: 'Avenir Pro',
      logo: 'A',
      location: 'Ben Arous',
      category: 'Emploi',
      description: 'Formation et insertion professionnelle',
      verified: true,
      campaigns: 10,
      totalDonations: 42300
    },
    {
      id: 6,
      name: 'Bien-Être',
      logo: 'B',
      location: 'Manouba',
      category: 'Bien-être',
      description: 'Soutien psychosocial et santé mentale',
      verified: true,
      campaigns: 7,
      totalDonations: 19800
    },
    {
      id: 7,
      name: 'Main Tendue',
      logo: 'M',
      location: 'Tunis',
      category: 'Alimentation',
      description: 'Distribution alimentaire et aide d\'urgence',
      verified: true,
      campaigns: 9,
      totalDonations: 31200
    },
    {
      id: 8,
      name: 'Lumière de l\'Espoir',
      logo: 'L',
      location: 'Sfax',
      category: 'Éducation',
      description: 'Scolarisation des enfants défavorisés',
      verified: true,
      campaigns: 11,
      totalDonations: 48900
    },
    {
      id: 9,
      name: 'Cœur Actif',
      logo: 'C',
      location: 'Sousse',
      category: 'Santé',
      description: 'Campagnes de sensibilisation sanitaire',
      verified: false,
      campaigns: 3,
      totalDonations: 8500
    }
  ];

  filteredAssociations: Association[] = [];

  ngOnInit() {
    this.applyFilters();
  }

  applyFilters() {
    this.filteredAssociations = this.allAssociations.filter(assoc => {
      const matchesSearch = assoc.name.toLowerCase().includes(this.searchQuery.toLowerCase());
      const matchesCategory = !this.selectedCategory || assoc.category === this.selectedCategory;
      const matchesLocation = !this.selectedLocation || assoc.location === this.selectedLocation;
      
      return matchesSearch && matchesCategory && matchesLocation;
    });

    this.sortAssociations();
  }

  sortAssociations() {
    switch (this.sortBy) {
      case 'name':
        this.filteredAssociations.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case 'most-active':
        this.filteredAssociations.sort((a, b) => b.campaigns - a.campaigns);
        break;
      case 'most-funded':
        this.filteredAssociations.sort((a, b) => b.totalDonations - a.totalDonations);
        break;
    }
  }

  getLogoInitials(logo: string | undefined, name: string): string {
    return logo || name.charAt(0);
  }

  clearFilters() {
    this.searchQuery = '';
    this.selectedCategory = '';
    this.selectedLocation = '';
    this.sortBy = 'name';
    this.applyFilters();
  }
}
